result = 0
if $args[0] = 'slave':
	if slave_state = CONST_INT['slave_exist'] and (slave['age'] = CONST_INT['young_age'] or slave['age'] = CONST_INT['milf_age']):
		if slave['fear'] = 0 and slave['domini_dictum'] = 0 and slave['neg_raped'] = 0 and slave['neg_disgust'] = 0:
			if interaction_slave['res'] >= 0 and interaction_slave['sex_acceptance'] > 0:
				result = 1
				if args[1] = 1:
					result = 0
					if slave['virginity'] = 4 or (slave['jo9_meiki_known'] = 1 and (slave['virginity'] = 2 or slave['virginity'] = 3)):
						result = 1
					end
				end
			end
		end
	end
end
if $args[0] = 'assistant':
	if assistant_state = CONST_INT['slave_exist'] and (assistant['age'] = CONST_INT['young_age'] or assistant['age'] = CONST_INT['milf_age']):
		if assistant['fear'] = 0 and assistant['domini_dictum'] = 0 and assistant['neg_raped'] = 0 and assistant['neg_disgust'] = 0:
			if interaction_assistant['res'] >= 0 and interaction_assistant['sex_acceptance'] > 0:
				result = 1
				if args[1] = 1:
					result = 0
					if assistant['virginity'] = 4 or (assistant['jo9_meiki_known'] = 1 and (assistant['virginity'] = 2 or assistant['virginity'] = 3)):
						result = 1
					end
				end
			end
		end
	end
end

! JO9_TRAINING_V3: eligible primary lesson only; no change to success thresholds or secondary XP.
result = 0
if $interaction_type = 'self_sex_lesson' or $interaction_type = 'self_sex_lesson_assistant':
 if $args[1] = 'slave["sub_threesome"]' or $args[1] = 'slave["sub_dp"]' or $args[1] = 'slave["sub_tp"]' or $args[1] = 'slave["sub_gangbang"]' or $args[1] = 'slave["sub_bukkake"]':
  if $args[0] = 'slave':
   if interaction_slave['diligence'] > 0 and func('jo9_meiki_willing', 'slave', 1) = 1:
    result = 1
   end
  end
  if $args[0] = 'assistant':
   if interaction_assistant['diligence'] > 0 and func('jo9_meiki_willing', 'assistant', 1) = 1:
    result = 1
   end
  end
 end
end
